import { ButtonLink, PageContainer } from "@qhkg/react";

import { MobileNav, type NavigationItem } from "../mobile-nav/mobile-nav";

export interface HeaderProps {
  action?: NavigationItem;
  brandName?: string;
  homeHref?: string;
  items: readonly NavigationItem[];
}

/**
 * Responsive application header. Keep route awareness in the application and
 * pass one current item so desktop and mobile navigation stay synchronized.
 */
export function Header({
  action,
  brandName = "QH 工作台",
  homeHref = "#home",
  items,
}: HeaderProps) {
  return (
    <header className="border-b border-border bg-surface">
      <PageContainer className="grid min-h-16 grid-cols-[auto_1fr_auto] items-center gap-2 py-2">
        <ButtonLink href={homeHref} variant="ghost">
          {brandName}
        </ButtonLink>

        <nav aria-label="主导航" className="hidden md:block">
          <ul className="flex list-none items-center justify-center gap-1 p-0">
            {items.map((item) => (
              <li key={item.href}>
                <ButtonLink
                  aria-current={item.current ? "page" : undefined}
                  href={item.href}
                  variant={item.current ? "secondary" : "ghost"}
                >
                  {item.label}
                </ButtonLink>
              </li>
            ))}
          </ul>
        </nav>

        <div className="flex items-center justify-end gap-2">
          {action ? (
            <ButtonLink href={action.href}>{action.label}</ButtonLink>
          ) : null}
          <MobileNav
            items={items}
            title={`${brandName}导航`}
            triggerClassName="md:hidden"
          />
        </div>
      </PageContainer>
    </header>
  );
}

"use client";

import { Button, ButtonLink, Drawer, IconButton } from "@qhkg/react";
import type { DrawerProps } from "@qhkg/react";

export interface NavigationItem {
  current?: boolean;
  href: string;
  label: string;
}

export interface MobileNavProps
  extends Pick<DrawerProps, "defaultOpen" | "onOpenChange" | "open"> {
  action?: NavigationItem;
  description?: string;
  items: readonly NavigationItem[];
  title?: string;
  triggerClassName?: string;
  triggerLabel?: string;
}

/**
 * Mobile primary navigation built on QH Drawer. Replace href values with the
 * consuming application's routes and derive current from its router.
 */
export function MobileNav({
  action,
  defaultOpen,
  description = "选择要前往的工作区页面。",
  items,
  onOpenChange,
  open,
  title = "主导航",
  triggerClassName,
  triggerLabel = "打开主导航",
}: MobileNavProps) {
  return (
    <Drawer defaultOpen={defaultOpen} open={open} onOpenChange={onOpenChange}>
      <Drawer.Trigger asChild>
        <IconButton
          aria-label={triggerLabel}
          className={triggerClassName}
          variant="secondary"
        >
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
            <path
              d="M4 7h16M4 12h16M4 17h16"
              strokeLinecap="round"
              strokeWidth="2"
            />
          </svg>
        </IconButton>
      </Drawer.Trigger>
      <Drawer.Content>
        <Drawer.Title>{title}</Drawer.Title>
        <Drawer.Description>{description}</Drawer.Description>
        <nav aria-label="移动端主导航">
          <ul className="grid list-none gap-2 p-0">
            {items.map((item) => (
              <li key={item.href}>
                <Drawer.Close asChild>
                  <ButtonLink
                    aria-current={item.current ? "page" : undefined}
                    className="w-full justify-start"
                    href={item.href}
                    variant={item.current ? "secondary" : "ghost"}
                  >
                    {item.label}
                  </ButtonLink>
                </Drawer.Close>
              </li>
            ))}
          </ul>
        </nav>
        <Drawer.Footer>
          <Drawer.Close asChild>
            <Button variant="secondary">关闭</Button>
          </Drawer.Close>
          {action ? (
            <Drawer.Close asChild>
              <ButtonLink href={action.href}>{action.label}</ButtonLink>
            </Drawer.Close>
          ) : null}
        </Drawer.Footer>
      </Drawer.Content>
    </Drawer>
  );
}
